-- CAL-001 Phase B: immutable, authoritative market calendar releases.
--
-- The payload below is a compact replay of the content-addressed Phase A
-- snapshot set `cal-001-2026-08-17`. Raw snapshot bytes remain in the
-- content-addressed repository and are authenticated by the offline verifier;
-- they are not stored in PostgreSQL. PostgreSQL 16 core sha256(bytea) verifies
-- canonical normalized day rows and the persisted full source-manifest metadata
-- aggregate (called the source bundle hash) before seal. No migration-time
-- network access or optional extension is used.

CREATE TABLE market_calendars (
    code            varchar(60) PRIMARY KEY,
    authority       varchar(120) NOT NULL,
    time_zone       varchar(60) NOT NULL,
    created_at      timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT chk_market_calendars_code CHECK (code ~ '^[a-z0-9_]+$'),
    CONSTRAINT chk_market_calendars_time_zone CHECK (time_zone = 'Europe/Istanbul')
);

CREATE TABLE market_calendar_releases (
    id                     uuid PRIMARY KEY,
    calendar_code          varchar(60) NOT NULL,
    snapshot_set_id        varchar(100) NOT NULL,
    release_version        integer NOT NULL,
    coverage_from          date NOT NULL,
    coverage_through       date NOT NULL,
    row_count              integer NOT NULL,
    normalized_sha256      char(64) NOT NULL,
    source_bundle_sha256   char(64) NOT NULL,
    released_at            timestamptz NOT NULL,
    sealed_at              timestamptz NULL,
    created_at             timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT fk_market_calendar_releases_calendar FOREIGN KEY (calendar_code)
        REFERENCES market_calendars(code) ON DELETE RESTRICT,
    CONSTRAINT uq_market_calendar_releases_calendar_version UNIQUE (calendar_code, release_version),
    CONSTRAINT uq_market_calendar_releases_calendar_id UNIQUE (calendar_code, id),
    CONSTRAINT chk_market_calendar_releases_version CHECK (release_version > 0),
    CONSTRAINT chk_market_calendar_releases_coverage CHECK (coverage_from <= coverage_through),
    CONSTRAINT chk_market_calendar_releases_row_count CHECK (
        row_count = coverage_through - coverage_from + 1),
    CONSTRAINT chk_market_calendar_releases_hashes CHECK (
        normalized_sha256 ~ '^[0-9a-f]{64}$' AND source_bundle_sha256 ~ '^[0-9a-f]{64}$')
);

CREATE TABLE market_calendar_release_sources (
    release_id       uuid NOT NULL,
    source_id        varchar(100) NOT NULL,
    source_kind      varchar(50) NOT NULL,
    source_role      varchar(30) NOT NULL,
    source_uri       text NOT NULL,
    media_type       varchar(100) NOT NULL,
    retrieved_at     timestamptz NOT NULL,
    raw_sha256       char(64) NOT NULL,
    snapshot_path    text NOT NULL,
    source_year      integer NULL,
    source_month     integer NULL,
    PRIMARY KEY (release_id, source_id),
    CONSTRAINT fk_market_calendar_release_sources_release FOREIGN KEY (release_id)
        REFERENCES market_calendar_releases(id) ON DELETE RESTRICT,
    CONSTRAINT uq_market_calendar_release_sources_hash UNIQUE (release_id, raw_sha256),
    CONSTRAINT chk_market_calendar_release_sources_role CHECK (source_role IN ('authority','discovery','policy')),
    CONSTRAINT chk_market_calendar_release_sources_hash CHECK (raw_sha256 ~ '^[0-9a-f]{64}$'),
    CONSTRAINT chk_market_calendar_release_sources_month CHECK (source_month IS NULL OR source_month BETWEEN 1 AND 12)
);

CREATE TABLE market_calendar_days (
    release_id             uuid NOT NULL,
    calendar_date          date NOT NULL,
    observation_expected   boolean NOT NULL,
    market_state           varchar(30) NOT NULL,
    reason_code            varchar(60) NOT NULL,
    evidence_raw_sha256    char(64) NOT NULL,
    PRIMARY KEY (release_id, calendar_date),
    CONSTRAINT fk_market_calendar_days_release FOREIGN KEY (release_id)
        REFERENCES market_calendar_releases(id) ON DELETE RESTRICT,
    CONSTRAINT fk_market_calendar_days_evidence FOREIGN KEY (release_id, evidence_raw_sha256)
        REFERENCES market_calendar_release_sources(release_id, raw_sha256) ON DELETE RESTRICT,
    CONSTRAINT chk_market_calendar_days_state CHECK (
        market_state IN ('publication','no_publication','full_session','partial_session','closed')),
    CONSTRAINT chk_market_calendar_days_semantics CHECK (
        (observation_expected AND market_state IN ('publication','full_session','partial_session'))
        OR (NOT observation_expected AND market_state IN ('no_publication','closed')))
);

CREATE TABLE market_calendar_active_releases (
    calendar_code    varchar(60) PRIMARY KEY,
    release_id       uuid NOT NULL UNIQUE,
    activated_at     timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT fk_market_calendar_active_release FOREIGN KEY (calendar_code, release_id)
        REFERENCES market_calendar_releases(calendar_code, id) ON DELETE RESTRICT
);

CREATE TABLE asset_market_calendars (
    asset_id          uuid PRIMARY KEY,
    source            varchar(30) NOT NULL,
    calendar_code     varchar(60) NOT NULL,
    bound_at          timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT fk_asset_market_calendars_asset FOREIGN KEY (asset_id)
        REFERENCES assets(id) ON DELETE RESTRICT,
    CONSTRAINT fk_asset_market_calendars_calendar FOREIGN KEY (calendar_code)
        REFERENCES market_calendars(code) ON DELETE RESTRICT,
    CONSTRAINT chk_asset_market_calendars_source CHECK (
        (source = 'tcmb' AND calendar_code = 'tcmb_indicative_fx')
        OR (source = 'twelvedata' AND calendar_code = 'bist_pay_xist'))
);

ALTER TABLE ingestion_windows
    ADD COLUMN calendar_release_id uuid NULL,
    ADD CONSTRAINT fk_ingestion_windows_calendar_release
        FOREIGN KEY (calendar_release_id) REFERENCES market_calendar_releases(id) ON DELETE RESTRICT;

CREATE INDEX idx_market_calendar_days_expected
    ON market_calendar_days(release_id, calendar_date, observation_expected);
CREATE INDEX idx_ingestion_windows_calendar_release
    ON ingestion_windows(calendar_release_id) WHERE calendar_release_id IS NOT NULL;

