00-0000-7000-8000-000000000001","range_from":"2026-04-01","range_through":"2026-04-30","raw_sha256":"b6446370365f5d5053ee0dbfc0d058e0b4e168dff25ec8753dd2b446c238c3e2"},{"release_id":"ca100000-0000-7000-8000-000000000001","range_from":"2026-05-01","range_through":"2026-05-31","raw_sha256":"728f2a0d23c7b936518d66e30b753bc5f60893f8692127a996d6140acb432848"},{"release_id":"ca100000-0000-7000-8000-000000000001","range_from":"2026-06-01","range_through":"2026-06-30","raw_sha256":"714cb09e07669865785a1526b54a9c6729d598a87c09fdc94433be023f67eda1"},{"release_id":"ca100000-0000-7000-8000-000000000001","range_from":"2026-07-01","range_through":"2026-07-31","raw_sha256":"d8061a76268026328638fb0a8c6c1594f62d87e68b9e9747c5d84264cfb7a226"},{"release_id":"ca100000-0000-7000-8000-000000000001","range_from":"2026-08-01","range_through":"2026-08-17","raw_sha256":"376d6273286d55ef026e5a5071358229944cd260e8d4c4decb94afd66a37c527"},{"release_id":"ca100000-0000-7000-8000-000000000002","range_from":"2024-01-01","range_through":"2024-12-31","raw_sha256":"066f184d546a6883159025f5a777c6893102a8c023f7c8af58a931f9329fca1d"},{"release_id":"ca100000-0000-7000-8000-000000000002","range_from":"2025-01-01","range_through":"2025-12-31","raw_sha256":"55d639083395fb1374718582d5cf439a70855ad49fe321379b2c53991eeaf182"},{"release_id":"ca100000-0000-7000-8000-000000000002","range_from":"2026-01-01","range_through":"2026-12-31","raw_sha256":"e45fa97e2f67d85b3571ce9e6c4758292a57379c2216fc88183f32504584e680"}]$evidence_payload$::jsonb) AS evidence(
    release_id uuid, range_from date, range_through date, raw_sha256 char(64));

INSERT INTO market_calendar_days(
    release_id, calendar_date, observation_expected, market_state, reason_code, evidence_raw_sha256)
SELECT masks.release_id,
       days.calendar_date,
       flags.expected,
       CASE
         WHEN masks.calendar_code = 'tcmb_indicative_fx' AND flags.expected THEN 'publication'
         WHEN masks.calendar_code = 'tcmb_indicative_fx' THEN 'no_publication'
         WHEN flags.partial THEN 'partial_session'
         WHEN flags.expected THEN 'full_session'
         ELSE 'closed'
       END,
       CASE
         WHEN masks.calendar_code = 'tcmb_indicative_fx' AND flags.expected THEN 'official_archive_link'
         WHEN masks.calendar_code = 'tcmb_indicative_fx' THEN 'official_archive_absence'
         WHEN flags.partial THEN 'official_partial_session'
         WHEN flags.official_closed THEN 'official_no_session'
         WHEN flags.expected THEN 'regular_weekday'
         ELSE 'weekend'
       END,
       evidence.raw_sha256
  FROM calendar_seed_masks masks
  JOIN market_calendar_releases release ON release.id = masks.release_id
 CROSS JOIN LATERAL generate_series(
       release.coverage_from, release.coverage_through, interval '1 day') days(calendar_date)
 CROSS JOIN LATERAL (
       SELECT substring(masks.expected_mask FROM (days.calendar_date::date - masks.coverage_from + 1) FOR 1) = '1' AS expected,
              substring(masks.partial_mask FROM (days.calendar_date::date - masks.coverage_from + 1) FOR 1) = '1' AS partial,
              substring(masks.official_closed_mask FROM (days.calendar_date::date - masks.coverage_from + 1) FOR 1) = '1' AS official_closed
 ) flags
  JOIN calendar_seed_evidence evidence
    ON evidence.release_id = masks.release_id
   AND days.calendar_date::date BETWEEN evidence.range_from AND evidence.range_through;

-- Shared trust gate for bootstrap and every future importer seal transition.
CREATE FUNCTION public.verify_market_calendar_release_payload(target_release_id uuid)
RETURNS boolean LANGUAGE plpgsql
SET search_path = pg_catalog, public, pg_temp AS $verify_function$
DECLARE
    release_row public.market_calendar_releases%ROWTYPE;
    actual_count integer;
    actual_from date;
    actual_through date;
    actual_normalized_hash text;
    actual_source_hash text;
BEGIN
    SELECT * INTO STRICT release_row
      FROM public.market_calendar_releases WHERE id = target_release_id;
    SELECT pg_catalog.count(*), pg_catalog.min(calendar_date), pg_catalog.max(calendar_date),
               pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
                   'calendar_code,date,observation_expected,market_state,reason_code,evidence_raw_sha256' || E'\n' ||
                   pg_catalog.string_agg(
                       release_row.calendar_code || ',' || pg_catalog.to_char(calendar_date, 'YYYY-MM-DD') || ',' ||
                       pg_catalog.lower(observation_expected::text) || ',' || market_state || ',' || reason_code || ',' ||
                       evidence_raw_sha256 || E'\n',
                       '' ORDER BY calendar_date),
                   'UTF8')), 'hex')
      INTO actual_count, actual_from, actual_through, actual_normalized_hash
      FROM public.market_calendar_days WHERE release_id = release_row.id;

        SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(pg_catalog.string_agg(
                   source_id || E'\t' || source_kind || E'\t' || source_role || E'\t' ||
                   source_uri || E'\t' || media_type || E'\t' ||
                   pg_catalog.to_char(retrieved_at AT TIME ZONE 'UTC',
                       'YYYY-MM-DD"T"HH24:MI:SS"Z"') || E'\t' ||
                   raw_sha256 || E'\t' || snapshot_path || E'\t' ||
                   coalesce(source_year::text, '') || E'\t' ||
                   coalesce(source_month::text, '') || E'\n',
                   '' ORDER BY source_id COLLATE "C"), 'UTF8')), 'hex')
      INTO actual_source_hash
      FROM public.market_calendar_release_sources WHERE release_id = release_row.id;

    IF actual_count <> release_row.row_count
       OR actual_from IS DISTINCT FROM release_row.coverage_from
       OR actual_through IS DISTINCT FROM release_row.coverage_through
       OR actual_normalized_hash IS DISTINCT FROM release_row.normalized_sha256
       OR actual_source_hash IS DISTINCT FROM release_row.source_bundle_sha256 THEN
        RAISE EXCEPTION 'CAL-001 payload verification failed for %: count=% range=%..% normalized=% sources=%',
            release_row.calendar_code, actual_count, actual_from, actual_through,
            actual_normalized_hash, actual_source_hash USING ERRCODE = '55000';
    END IF;
    RETURN TRUE;
END
$verify_function$;

CREATE FUNCTION public.seal_market_calendar_release(target_release_id uuid)
RETURNS void LANGUAGE plpgsql
SET search_path = pg_catalog, public, pg_temp AS $seal_function$
DECLARE affected integer;
BEGIN
    PERFORM pg_catalog.set_config('saydin.calendar_seal_release_id', target_release_id::text, TRUE);
    UPDATE public.market_calendar_releases
       SET sealed_at = pg_catalog.clock_timestamp()
     WHERE id = target_release_id AND sealed_at IS NULL;
    GET DIAGNOSTICS affected = ROW_COUNT;
    IF affected <> 1 THEN
        RAISE EXCEPTION 'calendar release seal target missing/already sealed: %', target_release_id
            USING ERRCODE = '55000';
    END IF;
END
$seal_function$;

-- Sealing is an explicit privilege. The future dedicated one-shot release role
-- must receive EXECUTE directly; PUBLIC and ordinary runtime identities do not.
REVOKE ALL ON FUNCTION public.seal_market_calendar_release(uuid) FROM PUBLIC;

-- Fail closed if bootstrap replay is not byte-identical to Phase A output.
DO $verify_bootstrap$
DECLARE release_id uuid;
BEGIN
    FOR release_id IN SELECT id FROM public.market_calendar_releases ORDER BY calendar_code COLLATE "C"
    LOOP
        PERFORM public.verify_market_calendar_release_payload(release_id);
    END LOOP;
END
$verify_bootstrap$;

CREATE FUNCTION public.enforce_market_calendar_release_assembly()
RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, public, pg_temp AS $$
DECLARE payload_release_id uuid;
DECLARE payload_sealed_at timestamptz;
BEGIN
    IF TG_TABLE_NAME = 'market_calendar_releases' THEN
        IF TG_OP = 'TRUNCATE' THEN
            RAISE EXCEPTION 'market calendar release truncate rejected' USING ERRCODE = '55000';
        END IF;
        IF OLD.sealed_at IS NOT NULL THEN
            RAISE EXCEPTION 'sealed market calendar release mutation rejected: %', OLD.id
                USING ERRCODE = '55000';
        END IF;
        IF TG_OP = 'UPDATE' AND (
           NEW.sealed_at IS NULL
           OR pg_catalog.current_setting('saydin.calendar_seal_release_id', TRUE)
                IS DISTINCT FROM OLD.id::text
           OR (NEW.id, NEW.calendar_code, NEW.snapshot_set_id, NEW.release_version,
                NEW.coverage_from, NEW.coverage_through, NEW.row_count,
                NEW.normalized_sha256, NEW.source_bundle_sha256, NEW.released_at,
                NEW.created_at)
               IS DISTINCT FROM
               (OLD.id, OLD.calendar_code, OLD.snapshot_set_id, OLD.release_version,
                OLD.coverage_from, OLD.coverage_through, OLD.row_count,
                OLD.normalized_sha256, OLD.source_bundle_sha256, OLD.released_at,
                OLD.created_at)) THEN
            RAISE EXCEPTION 'only a metadata-identical NULL-to-non-NULL seal transition is allowed: %', OLD.id
                USING ERRCODE = '55000';
        END IF;
        IF TG_OP = 'UPDATE' THEN
            PERFORM public.verify_market_calendar_release_payload(OLD.id);
        END IF;
        IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'TRUNCATE' THEN
        RAISE EXCEPTION 'market calendar payload truncate rejected: %', TG_TABLE_NAME
            USING ERRCODE = '55000';
    END IF;
    IF TG_OP = 'UPDATE' AND NEW.release_id IS DISTINCT FROM OLD.release_id THEN
        RAISE EXCEPTION 'market calendar payload release membership is immutable: %', OLD.release_id
            USING ERRCODE = '55000';
    END IF;
    payload_release_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.release_id ELSE NEW.release_id END;
    SELECT sealed_at INTO payload_sealed_at
      FROM public.market_calendar_releases WHERE id = payload_release_id FOR UPDATE;
    IF payload_sealed_at IS NOT NULL THEN
        RAISE EXCEPTION 'sealed market calendar payload mutation rejected: %.% release=%',
            TG_TABLE_NAME, TG_OP, payload_release_id USING ERRCODE = '55000';
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END
$$;

CREATE TRIGGER trg_market_calendar_releases_immutable
BEFORE UPDATE OR DELETE ON market_calendar_releases
FOR EACH ROW EXECUTE FUNCTION public.enforce_market_calendar_release_assembly();
CREATE TRIGGER trg_market_calendar_releases_no_truncate
BEFORE TRUNCATE ON market_calendar_releases
FOR EACH STATEMENT EXECUTE FUNCTION public.enforce_market_calendar_release_assembly();
CREATE TRIGGER trg_market_calendar_release_sources_immutable
BEFORE INSERT OR UPDATE OR DELETE ON market_calendar_release_sources
FOR EACH ROW EXECUTE FUNCTION public.enforce_market_calendar_release_assembly();
CREATE TRIGGER trg_market_calendar_release_sources_no_truncate
BEFORE TRUNCATE ON market_calendar_release_sources
FOR EACH STATEMENT EXECUTE FUNCTION public.enforce_market_calendar_release_assembly();
CREATE TRIGGER trg_market_calendar_days_immutable
BEFORE INSERT OR UPDATE OR DELETE ON market_calendar_days
FOR EACH ROW EXECUTE FUNCTION public.enforce_market_calendar_release_assembly();
CREATE TRIGGER trg_market_calendar_days_no_truncate
BEFORE TRUNCATE ON market_calendar_days
FOR EACH STATEMENT EXECUTE FUNCTION public.enforce_market_calendar_release_assembly();

CREATE FUNCTION public.enforce_active_market_calendar_release()
RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
    IF TG_OP IN ('DELETE', 'TRUNCATE') THEN
        RAISE EXCEPTION 'active market calendar pointer removal rejected: %', TG_OP
            USING ERRCODE = '55000';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.market_calendar_releases release
         WHERE release.id = NEW.release_id
           AND release.calendar_code = NEW.calendar_code
           AND release.sealed_at IS NOT NULL) THEN
        RAISE EXCEPTION 'active pointer requires matching sealed release: %/%',
            NEW.calendar_code, NEW.release_id USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END
$$;
CREATE TRIGGER trg_market_calendar_active_release_sealed
BEFORE INSERT OR UPDATE OR DELETE ON market_calendar_active_releases
FOR EACH ROW EXECUTE FUNCTION public.enforce_active_market_calendar_release();
CREATE TRIGGER trg_market_calendar_active_releases_no_truncate
BEFORE TRUNCATE ON market_calendar_active_releases
FOR EACH STATEMENT EXECUTE FUNCTION public.enforce_active_market_calendar_release();

CREATE FUNCTION public.activate_market_calendar_release(
    target_calendar_code text,
    target_release_id uuid,
    expected_current_release_id uuid)
RETURNS void LANGUAGE plpgsql
SET search_path = pg_catalog, public, pg_temp AS $activate_function$
DECLARE current_release_id uuid;
DECLARE affected integer;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.market_calendar_releases release
         WHERE release.id = target_release_id
           AND release.calendar_code = target_calendar_code
           AND release.sealed_at IS NOT NULL) THEN
        RAISE EXCEPTION 'activation target must be a matching sealed release: %/%',
            target_calendar_code, target_release_id USING ERRCODE = '23514';
    END IF;

    SELECT release_id INTO current_release_id
      FROM public.market_calendar_active_releases
     WHERE calendar_code = target_calendar_code
     FOR UPDATE;
    IF current_release_id IS NULL THEN
        RAISE EXCEPTION 'active calendar pointer missing: %', target_calendar_code
            USING ERRCODE = '55000';
    END IF;
    IF current_release_id = target_release_id THEN RETURN; END IF;
    IF current_release_id <> expected_current_release_id THEN
        RAISE EXCEPTION 'active calendar pointer conflict: % expected=% actual=%',
            target_calendar_code, expected_current_release_id, current_release_id
            USING ERRCODE = '40001';
    END IF;

    UPDATE public.market_calendar_active_releases
       SET release_id = target_release_id,
           activated_at = pg_catalog.clock_timestamp()
     WHERE calendar_code = target_calendar_code
       AND release_id = expected_current_release_id;
    GET DIAGNOSTICS affected = ROW_COUNT;
    IF affected <> 1 THEN
        RAISE EXCEPTION 'active calendar pointer compare-and-swap failed: %',
            target_calendar_code USING ERRCODE = '40001';
    END IF;
END
$activate_function$;

REVOKE ALL ON FUNCTION public.activate_market_calendar_release(text,uuid,uuid) FROM PUBLIC;

CREATE FUNCTION public.enforce_asset_market_calendar_source()
RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, public, pg_temp AS $$
DECLARE actual_source text;
BEGIN
    IF TG_OP = 'TRUNCATE' THEN
        RAISE EXCEPTION 'asset market calendar binding truncate rejected'
            USING ERRCODE = '55000';
    END IF;
    IF TG_OP IN ('UPDATE', 'DELETE') THEN
        RAISE EXCEPTION 'asset market calendar binding is immutable: %', OLD.asset_id
            USING ERRCODE = '55000';
    END IF;
    SELECT source INTO actual_source FROM public.assets WHERE id = NEW.asset_id;
    IF actual_source IS DISTINCT FROM NEW.source
       OR (NEW.source = 'tcmb' AND NEW.calendar_code <> 'tcmb_indicative_fx')
       OR (NEW.source = 'twelvedata' AND NEW.calendar_code <> 'bist_pay_xist') THEN
        RAISE EXCEPTION 'asset/calendar source mismatch for %', NEW.asset_id USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END
$$;
CREATE TRIGGER trg_asset_market_calendar_source
BEFORE INSERT OR UPDATE OR DELETE ON asset_market_calendars
FOR EACH ROW EXECUTE FUNCTION public.enforce_asset_market_calendar_source();
CREATE TRIGGER trg_asset_market_calendars_no_truncate
BEFORE TRUNCATE ON asset_market_calendars
FOR EACH STATEMENT EXECUTE FUNCTION public.enforce_asset_market_calendar_source();

CREATE FUNCTION public.provision_asset_market_calendar()
RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
    IF TG_OP = 'UPDATE' AND OLD.source IS DISTINCT FROM NEW.source
       AND (OLD.source IN ('tcmb','twelvedata') OR NEW.source IN ('tcmb','twelvedata')) THEN
        RAISE EXCEPTION 'calendar-bound asset source is immutable: %', OLD.id
            USING ERRCODE = '55000';
    END IF;
    IF TG_OP = 'INSERT' AND NEW.source IN ('tcmb','twelvedata') THEN
        INSERT INTO public.asset_market_calendars(asset_id,source,calendar_code)
        VALUES (NEW.id, NEW.source,
                CASE NEW.source WHEN 'tcmb' THEN 'tcmb_indicative_fx' ELSE 'bist_pay_xist' END);
    END IF;
    RETURN NEW;
END
$$;
CREATE TRIGGER trg_assets_calendar_source_immutable
BEFORE UPDATE OF source ON assets
FOR EACH ROW EXECUTE FUNCTION public.provision_asset_market_calendar();
CREATE TRIGGER trg_assets_calendar_provision
AFTER INSERT ON assets
FOR EACH ROW EXECUTE FUNCTION public.provision_asset_market_calendar();

CREATE FUNCTION public.enforce_ingestion_window_calendar_release()
RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
    IF TG_OP = 'UPDATE' AND OLD.calendar_release_id IS NOT NULL
       AND NEW.calendar_release_id IS DISTINCT FROM OLD.calendar_release_id THEN
        RAISE EXCEPTION 'ingestion window calendar release is immutable: %', OLD.id
            USING ERRCODE = '55000';
    END IF;
    IF TG_OP = 'UPDATE' AND OLD.calendar_release_id IS NOT NULL
       AND (NEW.source, NEW.asset_id, NEW.job_type, NEW.range_start,
            NEW.range_end, NEW.contract_version)
           IS DISTINCT FROM
           (OLD.source, OLD.asset_id, OLD.job_type, OLD.range_start,
            OLD.range_end, OLD.contract_version) THEN
        RAISE EXCEPTION 'bound ingestion window logical key is immutable: %', OLD.id
            USING ERRCODE = '55000';
    END IF;
    IF NEW.contract_version >= 2 AND NEW.source IN ('tcmb','twelvedata')
       AND NEW.state <> 'pending' AND NEW.calendar_release_id IS NULL THEN
        RAISE EXCEPTION 'contract-v2 calendar release is required: %', NEW.id
            USING ERRCODE = '23514';
    END IF;
    IF NEW.calendar_release_id IS NOT NULL AND NOT EXISTS (
        SELECT 1
          FROM public.asset_market_calendars binding
          JOIN public.market_calendar_releases release
            ON release.calendar_code = binding.calendar_code
           AND release.id = NEW.calendar_release_id
         WHERE binding.asset_id = NEW.asset_id
           AND binding.source = NEW.source
           AND release.sealed_at IS NOT NULL) THEN
        RAISE EXCEPTION 'calendar release is unsealed or does not match window asset/source: %', NEW.id
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END
$$;
CREATE TRIGGER trg_ingestion_window_calendar_release
BEFORE INSERT OR UPDATE ON ingestion_windows
FOR EACH ROW EXECUTE FUNCTION public.enforce_ingestion_window_calendar_release();

-- Seal is a one-way metadata-only transition. The triggers above reject every
-- later source/day/metadata mutation, and active pointers accept only sealed releases.
DO $seal_bootstrap$
DECLARE release_id uuid;
BEGIN
    FOR release_id IN SELECT id FROM public.market_calendar_releases ORDER BY calendar_code COLLATE "C"
    LOOP
        PERFORM public.seal_market_calendar_release(release_id);
    END LOOP;
END
$seal_bootstrap$;

INSERT INTO market_calendar_active_releases(calendar_code, release_id) VALUES
    ('tcmb_indicative_fx', 'ca100000-0000-7000-8000-000000000001'),
    ('bist_pay_xist', 'ca100000-0000-7000-8000-000000000002');

INSERT INTO asset_market_calendars(asset_id, source, calendar_code)
SELECT id, source,
       CASE source WHEN 'tcmb' THEN 'tcmb_indicative_fx' ELSE 'bist_pay_xist' END
  FROM assets
 WHERE source IN ('tcmb','twelvedata');

-- Backward-compatible, one-way projection for legacy contract-v1 readers.
INSERT INTO market_holidays(asset_id, holiday_date, reason)
SELECT binding.asset_id, day.calendar_date,
       'authoritative:' || binding.calendar_code || ':' || day.reason_code
  FROM asset_market_calendars binding
  JOIN market_calendar_active_releases active USING (calendar_code)
  JOIN market_calendar_days day ON day.release_id = active.release_id
 WHERE NOT day.observation_expected
ON CONFLICT (asset_id, holiday_date) DO NOTHING;

COMMENT ON TABLE market_calendar_releases IS
    'Immutable authoritative release metadata; active selection lives only in market_calendar_active_releases.';
COMMENT ON TABLE market_calendar_days IS
    'Immutable daily observation/session contract replayed and SHA-256 verified from CAL-001 Phase A.';
COMMENT ON COLUMN ingestion_windows.calendar_release_id IS
    'Immutable calendar release bound atomically by the first contract-v2 claim; retries reuse it.';
